def check_triple(x, y, z):
    return x**3 + y**3 + z**3 - x**2 * y**2 * z**2 == 0

solutions = []
for x in range(1, 11):
    for y in range(x, 11):
        for z in range(y, 11):
            if check_triple(x, y, z):
                solutions.append((x, y, z))

print("Solutions found:")
for sol in solutions:
    print(sol)
